    pub async fn update(
        &self,
        id: RedmineId,
        payload: &UpdateGroupPayload,
    ) -> Result<(), RedmineError> {
        let path = format!("/groups/{id}.json");
        let body = json!({ "group": payload });
        self.http
            .put::<serde_json::Value, _>(&path, &body, "groups.update")
            .await?;
        Ok(())
    }

